  function localizeTeam(key,map){
    const team=TEAM_DATA[key],rename=name=>map[name]||name;
    team.nameAliases={...map};
    team.roster=team.roster.map(([name,...rest])=>[rename(name),...rest]);
    team.formations=team.formations.map(form=>({...form,lines:form.lines.map(row=>row.map(rename))}));
    team.combos=team.combos.map(move=>({...move,members:move.members.map(rename)}));
    team.tactics=team.tactics.map(tactic=>({...tactic,members:tactic.members.map(rename)}));
    team.skillDetails=Object.fromEntries(Object.entries(team.skillDetails).map(([name,details])=>[rename(name),details]));
  }
  for(const [key,map] of Object.entries(localizedNames))localizeTeam(key,map);

